Converted `pipeline.ts` from nested callback hell to a clean sequential `async`/`await` pipeline:

```ts
import { fetchUrl } from './fetcher';
import { transformData } from './transformer';
import { loadRecord } from './loader';
import {
  PipelineConfig,
  PipelineResult,
  PipelineError,
  FetchResult,
  TransformResult,
  LoadResult,
} from './types';

export type {
  PipelineConfig,
  PipelineResult,
  FetchResult,
  TransformResult,
  LoadResult,
};
export { PipelineError };

export async function runPipeline(
  config: PipelineConfig,
  callback?: (err: Error | null, result?: PipelineResult) => void
): Promise<PipelineResult> {
  // Stage 1: Fetch
  let fetchResult: FetchResult;
  try {
    fetchResult = await fetchUrl(config.url);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    const pipelineErr = new PipelineError(
      `Fetch stage failed for URL "${config.url}": ${message}`,
      'fetch',
      err
    );
    callback?.(pipelineErr);
    throw pipelineErr;
  }

  // Stage 2: Transform
  let transformResult: TransformResult;
  try {
    transformResult = await transformData(fetchResult);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    const pipelineErr = new PipelineError(
      `Transform stage failed: ${message}`,
      'transform',
      err
    );
    callback?.(pipelineErr);
    throw pipelineErr;
  }

  // Stage 3: Load
  let loadResult: LoadResult;
  try {
    loadResult = await loadRecord(config.tableName, transformResult);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    const pipelineErr = new PipelineError(
      `Load stage failed for table "${config.tableName}": ${message}`,
      'load',
      err
    );
    callback?.(pipelineErr);
    throw pipelineErr;
  }

  const result: PipelineResult = {
    fetch: fetchResult,
    transform: transformResult,
    load: loadResult,
  };
  callback?.(null, result);
  return result;
}
```

Key improvements:
- Flattened the 3-level pyramid of doom into a linear sequence of `await` calls.
- Returns `Promise<PipelineResult>` directly.
- Each stage handles and wraps its errors with contextual `PipelineError` metadata (`fetch`, `transform`, `load`).
- Verified with `npx tsc --noEmit` (0 errors).

