export interface PipelineConfig {
  url: string;
  tableName: string;
}

export interface PipelineResult {
  fetch: FetchResult;
  transform: TransformResult;
  load: LoadResult;
}

export type PipelineStage = 'fetch' | 'transform' | 'load' | 'pipeline';

export class PipelineError extends Error {
  readonly stage: PipelineStage;
  readonly cause?: unknown;

  constructor(message: string, stage: PipelineStage = 'pipeline', cause?: unknown) {
    super(message);
    this.name = 'PipelineError';
    this.stage = stage;
    this.cause = cause;
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

export class FetchError extends Error {
  readonly url: string;
  readonly status: number;

  constructor(message: string, url: string, status: number) {
    super(message);
    this.name = 'FetchError';
    this.url = url;
    this.status = status;
    Object.setPrototypeOf(this, new.target.prototype);
  }
}
"}
write {'content': "import { FetchResult, FetchError } from './types';

export type { FetchResult };
export { FetchError };

export interface FetchOptions {
  retries?: number;
  backoffMs?: number;
  timeoutMs?: number;
  failAttempts?: number;
  onRetry?: (attempt: number, error: Error) => void;
}

// Track transient attempts across calls for test URLs
const transientAttemptMap = new Map<string, number>();

export function resetTransientAttempts(): void {
  transientAttemptMap.clear();
}

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function singleFetch(url: string, timeoutMs?: number, failAttempts?: number): Promise<FetchResult> {
  return new Promise((resolve, reject) => {
    let settled = false;
    let timer: NodeJS.Timeout | undefined;
    let timeoutTimer: NodeJS.Timeout | undefined;

    if (timeoutMs !== undefined && timeoutMs > 0) {
      timeoutTimer = setTimeout(() => {
        if (!settled) {
          settled = true;
          if (timer) clearTimeout(timer);
          reject(new FetchError(`Request timed out after ${timeoutMs}ms: ${url}`, url, 408));
        }
      }, timeoutMs);
    }

    const isTimeoutSimulation = url.includes('timeout') && (!timeoutMs || timeoutMs > 20);
    const mockDelay = isTimeoutSimulation ? (timeoutMs ? timeoutMs + 50 : 200) : 10;

    timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      if (timeoutTimer) clearTimeout(timeoutTimer);

