write {'content': "export interface FetchResult {
  url: string;
  status: number;
  data: string;
}

export interface TransformResult {
  id: number;
  slug: string;
  sourceUrl: string;
  transformedAt: string;
}

export interface LoadResult {
  insertedId: number;
  table: string;
  success: boolean;
}

export interface PipelineConfig {
  url: string;
  tableName: string;
}

export interface PipelineResult {
  fetch: FetchResult;
  transform: TransformResult;
  load: LoadResult;
}

export type PipelineStage = 'fetch' | 'transform' | 'load' | 'pipeline';

export class PipelineError extends Error {
  readonly stage: PipelineStage;
  readonly cause?: unknown;

  constructor(message: string, stage: PipelineStage = 'pipeline', cause?: unknown) {
    super(message);
    this.name = 'PipelineError';
    this.stage = stage;
    this.cause = cause;
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

export class PipelineStageError extends PipelineError {
  readonly originalError?: unknown;

  constructor(message: string, stage: PipelineStage, cause?: unknown) {
    super(message, stage, cause);
    this.name = 'PipelineStageError';
    this.originalError = cause;
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

export class FetchError extends Error {
  readonly url: string;
  readonly status: number;

  constructor(message: string, url: string, status: number) {
    super(message);
    this.name = 'FetchError';
    this.url = url;
    this.status = status;
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

export class TransformError extends Error {
  readonly field: string;
  readonly expectedType: string;

  constructor(message: string, field: string, expectedType: string) {
    super(message);
    this.name = 'TransformError';
    this.field = field;
    this.expectedType = expectedType;
    Object.setPrototypeOf(this, new.target.prototype);
  }

  get fieldName(): string {
    return this.field;
  }
}

export class LoadError extends Error {
  readonly table: string;
  readonly operation: string;

  constructor(message: string, table: string, operation: string = 'insert') {
    super(message);
    this.name = 'LoadError';
    this.table = table;
    this.operation = operation;
    Object.setPrototypeOf(this, new.target.prototype);
  }

  get tableName(): string {
    return this.table;
  }
}
