import { runPipeline } from './pipeline';
import { PipelineError, PipelineStageError, TransformError } from './types';

describe('Data Pipeline', () => {
  it('successfully processes full pipeline (fetch -> transform -> load)', async () => {
    const result = await runPipeline({
      url: 'https://api.example.com/items',
      tableName: 'items_table',
    });

    expect(result).toBeDefined();
    expect(result.fetch.status).toBe(200);
    expect(result.fetch.url).toBe('https://api.example.com/items');

    expect(result.transform.slug).toBe('sample-payload');
    expect(result.transform.sourceUrl).toBe('https://api.example.com/items');
    expect(result.transform.id).toBe(1);

    expect(result.load.success).toBe(true);
    expect(result.load.insertedId).toBe(1);
    expect(result.load.table).toBe('items_table');
  });

  it('fails with PipelineError at fetch stage on invalid URL and wraps error correctly', async () => {
    await expect(
      runPipeline({
        url: 'invalid-url',
        tableName: 'items_table',
      })
    ).rejects.toThrow(PipelineError);

    try {
      await runPipeline({
        url: 'invalid-url',
        tableName: 'items_table',
      });
      expect.fail('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      expect(err).toBeInstanceOf(PipelineStageError);
      const pipelineErr = err as PipelineStageError;
      expect(pipelineErr.stage).toBe('fetch');
      expect(pipelineErr.message).toContain('Fetch stage failed');
      expect(pipelineErr.cause).toBeDefined();
    }
  });

  it('fails with PipelineError at fetch stage on 500 error URL', async () => {
    try {
      await runPipeline({
        url: 'https://api.example.com/error',
        tableName: 'items_table',
      });
      expect.fail('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      expect(err).toBeInstanceOf(PipelineStageError);
      const pipelineErr = err as PipelineStageError;
      expect(pipelineErr.stage).toBe('fetch');
      expect(pipelineErr.message).toContain('Fetch stage failed');
      expect(pipelineErr.cause).toBeDefined();
    }
  });

  it('fails with PipelineError at transform stage preserving context when TransformError occurs', async () => {
    const transformer = await import('./transformer');
    const transformErr = new TransformError('Missing required field: name', 'name', 'string');
    const spy = vi.spyOn(transformer, 'transformData').mockRejectedValueOnce(transformErr);

    try {
      await runPipeline({
        url: 'https://api.example.com/items',
        tableName: 'items_table',
      });
      expect.fail('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      expect(err).toBeInstanceOf(PipelineStageError);
      const pipelineErr = err as PipelineStageError;
      expect(pipelineErr.stage).toBe('transform');
      expect(pipelineErr.message).toContain('Transform stage failed');
      expect(pipelineErr.message).toContain('name');
      expect(pipelineErr.message).toContain('string');
      expect(pipelineErr.cause).toBe(transformErr);
      expect(pipelineErr.originalError).toBe(transformErr);
    } finally {
      spy.mockRestore();
    }
  });

  it('fails with PipelineError at load stage on missing table name', async () => {
    try {
      await runPipeline({
        url: 'https://api.example.com/items',
        tableName: '',
      });
      expect.fail('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      expect(err).toBeInstanceOf(PipelineStageError);
      const pipelineErr = err as PipelineStageError;
      expect(pipelineErr.stage).toBe('load');
      expect(pipelineErr.message).toContain('Load stage failed');
    }
  });
});

