### 2. `src/data-pipeline/pipeline.ts`
Refactored from nested callback hell into sequential `async/await` returning a `Promise<PipelineResult>` with structured `try...catch` blocks for each stage:

```ts
import { fetchUrl } from './fetcher';
import { transformData } from './transformer';
import { loadRecord } from './loader';
import {
  PipelineConfig,
  PipelineResult,
  PipelineError,
  PipelineStageError,
  FetchResult,
  TransformResult,
  LoadResult,
  FetchError,
  TransformError,
  LoadError,
} from './types';

export type {
  PipelineConfig,
  PipelineResult,
  FetchResult,
  TransformResult,
  LoadResult,
};
export { PipelineError, PipelineStageError };

export async function runPipeline(
  config: PipelineConfig
): Promise<PipelineResult> {
  const targetUrl = config.url ?? config.urls?.[0];
  if (!targetUrl) {
    throw new PipelineStageError(
      'Missing URL in pipeline configuration',
      'fetch'
    );
  }

  // Stage 1: Fetch
  let fetchResult: FetchResult;
  try {
    fetchResult = await fetchUrl(targetUrl);
  } catch (err) {
    if (err instanceof FetchError) {
      throw new PipelineStageError(
        `Fetch stage failed for URL "${err.url}" (status ${err.status}): ${err.message}`,
        'fetch',
        err
      );
    }
    const message = err instanceof Error ? err.message : String(err);
    throw new PipelineStageError(
      `Fetch stage failed for URL "${targetUrl}": ${message}`,
      'fetch',
      err
    );
  }

  // Stage 2: Transform
  let transformResult: TransformResult;
  try {
    transformResult = await transformData(fetchResult);
  } catch (err) {
    if (err instanceof TransformError) {
      throw new PipelineStageError(
        `Transform stage failed for field "${err.field}" (expected ${err.expectedType}): ${err.message}`,
        'transform',
        err
      );
    }
    const message = err instanceof Error ? err.message : String(err);
    throw new PipelineStageError(
      `Transform stage failed: ${message}`,
      'transform',
      err
    );
  }

  // Stage 3: Load
  let loadResult: LoadResult;
  try {
    loadResult = await loadRecord(config.tableName, transformResult);
  } catch (err) {
    if (err instanceof LoadError) {
      throw new PipelineStageError(
        `Load stage failed for table "${err.table}" during operation "${err.operation}": ${err.message}`,
        'load',
        err
      );
    }
    const message = err instanceof Error ? err.message : String(err);
    throw new PipelineStageError(
      `Load stage failed for table "${config.tableName}": ${message}`,
      'load',
      err
    );
  }

  return {
    fetch: fetchResult,
    transform: transformResult,
    load: loadResult,
  };
}

export async function runConcurrent(
  config: PipelineConfig
): Promise<PromiseSettledResult<PipelineResult>[]> {
  const urls = config.urls ?? (config.url ? [config.url] : []);
  if (urls.length === 0) {
    return [];
  }

  const concurrency = Math.max(1, config.concurrency ?? urls.length);
  const results: PromiseSettledResult<PipelineResult>[] = [];

  for (let i = 0; i < urls.length; i += concurrency) {
    const batch = urls.slice(i, i + concurrency);
    const batchPromises = batch.map((url) =>
      runPipeline({
        ...config,
        url,
      })
    );
    const batchResults = await Promise.allSettled(batchPromises);
    results.push(...batchResults);
  }

  return results;
}

export interface PipelineRunner {
  (config: PipelineConfig): Promise<PipelineResult>;
  run: (config: PipelineConfig) => Promise<PromiseSettledResult<PipelineResult>[]>;
  runPipeline: typeof runPipeline;
}

export const pipeline: PipelineRunner = Object.assign(
  (config: PipelineConfig) => runPipeline(config),
  {
    run: runConcurrent,
    runPipeline,
  }
);

export const run = runConcurrent;
